g.script:
(function(){
  var svg=document.documentElement,NS="http://www.w3.org/2000/svg";
  var W=1200,H=430,SEG=14,LEN=22;
  var pts=[],mouse={x:600,y:215},started=false;
  var formulas=["e^{iπ}+1=0","φ=1,618","∞","∫ Σ √","π≈3,14159","∇·E=ρ","ζ(s)","Fₙ=Fₙ₋₁+Fₙ₋₂","∂f/∂x","√2≈1,414","c=λf","E=mc²","lim 1/n","Σ1/n²","a²+b²=c²","0,1,1,2,3,5,8","2,3,5,7,11,13","∮E·dl","det(A)","rank(A)"];
  for(var i=0;i<SEG;i++){pts.push({x:600-i*LEN,y:215});}
  ["dragon-static","dragon-nodes","dragon-head","numbers-static"].forEach(function(id){
    var el=document.getElementById(id);if(el)el.setAttribute("display","none");
  });
  var bodyG=document.createElementNS(NS,"g");
  bodyG.setAttribute("fill","none");
  bodyG.setAttribute("stroke","url(#dg)");
  bodyG.setAttribute("stroke-width","2.6");
  bodyG.setAttribute("stroke-linecap","round");
  bodyG.setAttribute("stroke-linejoin","round");
  bodyG.setAttribute("filter","url(#dgl)");
  var bodyPath=document.createElementNS(NS,"path");
  bodyG.appendChild(bodyPath);
  svg.appendChild(bodyG);
  var nodeG=document.createElementNS(NS,"g");
  svg.appendChild(nodeG);
  var headG=document.createElementNS(NS,"g");
  headG.setAttribute("fill","#ffe3a0");
  var hc=document.createElementNS(NS,"circle");
  hc.setAttribute("r","10");hc.setAttribute("filter","url(#dgl)");
  headG.appendChild(hc);
  var e1=document.createElementNS(NS,"circle");e1.setAttribute("cx","-4");e1.setAttribute("cy","-3");e1.setAttribute("r","2.4");e1.setAttribute("fill","#0b0d12");
  var e2=document.createElementNS(NS,"circle");e2.setAttribute("cx","4");e2.setAttribute("cy","-3");e2.setAttribute("r","2.4");e2.setAttribute("fill","#0b0d12");
  headG.appendChild(e1);headG.appendChild(e2);
  svg.appendChild(headG);
  var tailEmit=0;
  svg.addEventListener("mousemove",function(e){
    var pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;
    var ctm=svg.getScreenCTM().inverse();
    var p=pt.matrixTransform(ctm);
    mouse.x=p.x;mouse.y=p.y;started=true;
  });
  svg.addEventListener("mouseleave",function(){started=false;});
  function spawnNum(){
    var tx=pts[SEG-1].x-30+Math.random()*40;
    var ty=pts[SEG-1].y-20+Math.random()*30;
    var t=document.createElementNS(NS,"text");
    t.setAttribute("x",tx);t.setAttribute("y",ty);
    t.setAttribute("text-anchor","middle");
    t.setAttribute("font-family","Georgia,serif");
    t.setAttribute("font-size","13");
    t.setAttribute("fill","#f0dcb2");
    t.setAttribute("opacity","0");
    t.textContent=formulas[Math.floor(Math.random()*formulas.length)];
    svg.appendChild(t);
    var start=Date.now(),dur=2400;
    function anim(){
      var k=(Date.now()-start)/dur;
      if(k>=1){svg.removeChild(t);return;}
      t.setAttribute("opacity",String(Math.sin(Math.PI*k)));
      t.setAttribute("transform","translate(0,"+(-k*55)+") scale("+(0.7+k*0.4)+")");
      requestAnimationFrame(anim);
    }
    requestAnimationFrame(anim);
  }
  function frame(){
    if(started){
      pts[0].x+=(mouse.x-pts[0].x)*0.18;
      pts[0].y+=(mouse.y-pts[0].y)*0.18;
    }else{
      var t=Date.now()*0.001;
      pts[0].x=600+Math.sin(t*0.7)*120;
      pts[0].y=215+Math.cos(t*0.5)*60;
    }
    for(var i=1;i<SEG;i++){
      var dx=pts[i-1].x-pts[i].x,dy=pts[i-1].y-pts[i].y;
      var d=Math.sqrt(dx*dx+dy*dy)||1;
      var nx=dx/d,ny=dy/d;
      pts[i].x=pts[i-1].x-nx*LEN;
      pts[i].y=pts[i-1].y-ny*LEN;
    }
    var d="M"+pts[0].x.toFixed(1)+","+pts[0].y.toFixed(1);
    for(var i=1;i<SEG;i++){d+=" L"+pts[i].x.toFixed(1)+","+pts[i].y.toFixed(1);}
    bodyPath.setAttribute("d",d);
    while(nodeG.firstChild){nodeG.removeChild(nodeG.firstChild);}
    for(var i=1;i<SEG;i++){
      var c=document.createElementNS(NS,"circle");
      var r=5.5*(1-i/SEG)+1.5;
      c.setAttribute("cx",pts[i].x.toFixed(1));c.setAttribute("cy",pts[i].y.toFixed(1));c.setAttribute("r",r.toFixed(1));
      c.setAttribute("fill",i/SEG>0.5?"#c0487e":"#f0dcb2");
      nodeG.appendChild(c);
    }
    headG.setAttribute("transform","translate("+pts[0].x.toFixed(1)+","+pts[0].y.toFixed(1)+")");
    tailEmit++;
    if(tailEmit%18===0){spawnNum();}
    requestAnimationFrame(frame);
  }
  frame();
})();
